INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000029f',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss art and society at B2","Use Kunst und Gesellschaft vocabulary","Talk about art''s social functions, German cultural policy, and public art debates"],"explanation":{"intro":"Art and society vocabulary covers art''s social functions, cultural policy, and Germany''s rich artistic tradition at B2.","culturalNote":"Kunst und Gesellschaft: Germany has a federally organised cultural policy (Kulturhoheit der Länder — state sovereignty over culture). Kulturfinanzierung (cultural funding — Rundfunkbeitrag, Kunstförderung). Germany: major museums (Staatliche Museen Berlin, Bayerische Staatsgemäldesammlungen), opera houses (Hamburg, Munich, Dresden), art fairs (Art Cologne, Art Düsseldorf). Key debates: Restitution (colonial objects — Humboldt Forum, Benin bronzes), NS-Raubkunst (Nazi-looted art — Commission for Looted Art in Europe). Documenta (Kassel — world''s largest contemporary art exhibition — every 5 years). Beuys: ''Every person is an artist.'' Censorship debate: Kunstfreiheit (art freedom — Art. 5 III GG — almost absolute, limits only at core of human dignity). Art as social critique."},"examples":[{"german":"Kunst entzieht sich einer rein funktionalistischen Betrachtungsweise: Sie dient nicht nur ästhetischem Genuss oder sozialem Prestige, sondern stellt symbolische Ordnungen infrage, schafft Räume für das Unsagbare und ermöglicht kollektive Verarbeitung von Erfahrungen, die in nüchternen Diskursen keinen Platz finden.","english":"Art eludes a purely functionalist perspective: it does not only serve aesthetic pleasure or social prestige, but questions symbolic orders, creates spaces for the unsayable, and enables collective processing of experiences that find no place in sober discourses."},{"german":"Die Debatte um die Rückgabe kolonialer Kulturgüter zeigt, dass Kunst kein neutrales Archiv der Menschheitsgeschichte ist, sondern durch Sammlungspraktiken der Vergangenheit geprägte Machtverhältnisse materialisiert — eine Erkenntnis, die etablierte Museumskonzepte grundlegend herausfordert.","english":"The debate about the return of colonial cultural goods shows that art is not a neutral archive of human history, but materialises power relations shaped by the collection practices of the past — an insight that fundamentally challenges established museum concepts."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss art''s social functions, colonial restitution debates, and Germany''s cultural policy at B2."}}',
'{"items":[{"word":"sich entziehen","translation":"to elude/resist","pronunciation":"zikh ent-TSEE-en","example":"Sich einer Betrachtung entziehen."},{"word":"das Unsagbare","translation":"the unsayable","pronunciation":"dahs oon-ZAH-kba-reh","example":"Räume für das Unsagbare."},{"word":"nüchtern","translation":"sober","pronunciation":"NÜ-khtern","example":"Nüchterne Diskurse."},{"word":"materialisieren","translation":"to materialise","pronunciation":"mah-teh-ri-ah-li-ZEER-en","example":"Machtverhältnisse materialisieren."},{"word":"herausfordern","translation":"to challenge","pronunciation":"heh-ROWS-for-dern","example":"Grundlegend herausfordern."},{"word":"die Rückgabe","translation":"return/restitution","pronunciation":"dee RÜK-gah-beh","example":"Rückgabe kolonialer Güter."}]}',
'{"title":"Sich einer X entziehen — to elude/resist X (refusing to submit to)","pattern":"etwas/jemand entzieht sich einer Sache = something/someone eludes, escapes, or resists something (sich entziehen + dative = to elude, to resist, to evade — the dative marks what is being resisted)","explanation":"Sich entziehen + dative = to elude, resist, escape (reflexive; entzieht sich). Kunst entzieht sich einer rein funktionalistischen Betrachtungsweise = Art eludes a purely functionalist perspective (dative: einer Betrachtungsweise — the perspective art resists). Unlike simple ''not fitting'' — entziehen suggests active resistance or structural incompatibility. Compare: sich einer Definition entziehen (to resist definition), der Logik entziehen (to defy logic), sich jeder Kategorisierung entziehen (to elude any categorisation). The dative-genitive split: sich entziehen takes dative; without the reflexive, entziehen takes dative object.","examples":[{"sentence":"Das Phänomen entzieht sich einer einfachen Erklärung.","translation":"The phenomenon eludes a simple explanation."},{"sentence":"Er entzieht sich jeder Kategorisierung.","translation":"He eludes any categorisation."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Unsagbare'' means?","options":["the unsayable","the unutterable","the ineffable","the inexpressible"],"correctAnswer":"the unsayable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Art eludes a purely functionalist perspective: it does not only serve aesthetic pleasure or social prestige, but questions symbolic orders, creates spaces for the unsayable, and enables collective processing of experiences that find no place in sober discourses.","options":["Kunst entzieht sich einer rein funktionalistischen Betrachtungsweise: Sie dient nicht nur ästhetischem Genuss oder sozialem Prestige, sondern stellt symbolische Ordnungen infrage, schafft Räume für das Unsagbare und ermöglicht kollektive Verarbeitung von Erfahrungen, die in nüchternen Diskursen keinen Platz finden.","Kunst ist mehr als Unterhaltung — sie ist gesellschaftliche Kritik und kollektives Gedächtnis.","Kunst hat viele Funktionen, die über Ästhetik hinausgehen.","Kunst schafft Räume für Erfahrungen, die sich nicht in Worte fassen lassen."],"correctAnswer":"Kunst entzieht sich einer rein funktionalistischen Betrachtungsweise: Sie dient nicht nur ästhetischem Genuss oder sozialem Prestige, sondern stellt symbolische Ordnungen infrage, schafft Räume für das Unsagbare und ermöglicht kollektive Verarbeitung von Erfahrungen, die in nüchternen Diskursen keinen Platz finden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Phänomen entzieht sich einer einfachen ___.","options":["Erklärung","Analyse","Beschreibung","Definition"],"correctAnswer":"Erklärung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He eludes any categorisation","wordBankItems":["Er","entzieht","sich","jeder","Kategorisierung","."],"correctAnswer":"Er entzieht sich jeder Kategorisierung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Nüchtern'' means?","options":["sober","dry","rational","detached"],"correctAnswer":"sober"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002a0',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss literature and language at B2","Use Literatur und Sprache vocabulary","Talk about German literature traditions, canon debates, and language as art"],"explanation":{"intro":"Literature and language vocabulary covers German literary tradition, canon debates, and the relationship between language and thought at B2.","culturalNote":"Literatur und Sprache: Germany''s great literary tradition: Goethe and Schiller (Weimar Classicism), Brecht (critical/political theatre), Kafka (modern alienation — though Austrian), Thomas Mann (bourgeois critique — Buddenbrooks, Der Zauberberg). Post-WWII: Gruppe 47, Heinrich Böll, Günter Grass, Christa Wolf. Contemporary: Herta Müller (Nobel 2009 — Romanian German), Jenny Erpenbeck, Daniel Kehlmann. Kanondebatten (canon debates — who is included/excluded — gender, migration background). Migrantenliteratur (migration literature — Özdamar, Biondi). Sprache und Macht (language and power — Klemperer''s LTI — language of the Third Reich). Buchmarkt (book market — Frankfurt Book Fair — largest in world)."},"examples":[{"german":"Literatur ist nicht bloß Unterhaltung, sondern ein privilegierter Modus des Weltzugangs: Sie ermöglicht die kontrollierte Zumutung des Fremden — Perspektiven, Schicksale und Wirklichkeiten, die dem Leser entzogen bleiben würden, wenn er sich allein auf unmittelbare Erfahrung verlässt.","english":"Literature is not merely entertainment, but a privileged mode of access to the world: it enables the controlled imposition of the unfamiliar — perspectives, fates, and realities that would remain inaccessible to the reader if they relied solely on immediate experience."},{"german":"Die Sprache ist nicht nur Werkzeug der Kommunikation, sondern das Medium, in dem wir denken und fühlen: Die Grenzen meiner Sprache bedeuten die Grenzen meiner Welt — ein Satz Wittgensteins, der auf Bildung und sprachliche Kompetenz als Bedingung der Weltwahrnehmung hinweist.","english":"Language is not only a tool of communication, but the medium in which we think and feel: the limits of my language mean the limits of my world — a sentence of Wittgenstein''s that points to education and linguistic competence as a condition of perceiving the world."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss German literature, canon debates, and the Wittgenstein language-world connection at B2."}}',
'{"items":[{"word":"privilegiert","translation":"privileged","pronunciation":"pri-vi-leh-GEERT","example":"Privilegierter Modus."},{"word":"die Zumutung","translation":"imposition/demand","pronunciation":"dee TSOO-moo-toong","example":"Kontrollierte Zumutung."},{"word":"entzogen bleiben","translation":"to remain inaccessible","pronunciation":"ent-TSOH-gen BLY-ben","example":"Dem Leser entzogen bleiben."},{"word":"hinweisen auf","translation":"to point to","pronunciation":"HIN-vy-zen owf","example":"Auf Kompetenz hinweisen."},{"word":"das Medium","translation":"medium","pronunciation":"dahs MAY-dee-oom","example":"Medium des Denkens."},{"word":"die Weltwahrnehmung","translation":"world perception","pronunciation":"dee VELT-vahr-nay-moong","example":"Weltwahrnehmung prägen."}]}',
'{"title":"Nicht bloß X, sondern Y — not merely X but Y (upgrading status or role)","pattern":"etwas ist nicht bloß X, sondern Y = something is not merely X, but Y (bloß = merely — stronger dismissal than ''nur''; sondern introduces the upgraded status)","explanation":"Nicht bloß X, sondern Y = not merely X, but Y. Bloß = merely (more dismissive than nur = only: bloß implies the X is an underestimate, not just one among several options). Nicht bloß Unterhaltung, sondern ein privilegierter Modus des Weltzugangs = Not merely entertainment, but a privileged mode of access to the world. The pattern argues that something has more dignity/importance/complexity than a reductive view (X) allows. Compare: nicht nur...sondern auch (not only...but also — less dismissive), nicht allein...sondern (not solely...but — correction of exclusive claim), mehr als (more than — simpler quantitative upgrade), nicht einfach X (not simply X — challenges oversimplification).","examples":[{"sentence":"Das Gespräch war nicht bloß Smalltalk, sondern ein echter Austausch.","translation":"The conversation was not merely small talk, but a genuine exchange."},{"sentence":"Vertrauen ist nicht bloß ein Gefühl, sondern eine soziale Institution.","translation":"Trust is not merely a feeling, but a social institution."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Zumutung'' means?","options":["imposition/demand","challenge","burden","provocation"],"correctAnswer":"imposition/demand"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Literature is not merely entertainment, but a privileged mode of access to the world: it enables the controlled imposition of the unfamiliar — perspectives, fates, and realities that would remain inaccessible to the reader if they relied solely on immediate experience.","options":["Literatur ist nicht bloß Unterhaltung, sondern ein privilegierter Modus des Weltzugangs: Sie ermöglicht die kontrollierte Zumutung des Fremden — Perspektiven, Schicksale und Wirklichkeiten, die dem Leser entzogen bleiben würden, wenn er sich allein auf unmittelbare Erfahrung verlässt.","Literatur gibt uns Zugang zu Erfahrungen, die wir selbst nie machen würden.","Gute Literatur zwingt uns, andere Perspektiven einzunehmen.","Literatur ist mehr als Unterhaltung: Sie ist eine Form der Welterkenntnis."],"correctAnswer":"Literatur ist nicht bloß Unterhaltung, sondern ein privilegierter Modus des Weltzugangs: Sie ermöglicht die kontrollierte Zumutung des Fremden — Perspektiven, Schicksale und Wirklichkeiten, die dem Leser entzogen bleiben würden, wenn er sich allein auf unmittelbare Erfahrung verlässt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Gespräch war nicht bloß Smalltalk, sondern ein echter ___.","options":["Austausch","Dialog","Gespräch","Diskurs"],"correctAnswer":"Austausch"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Trust is not merely a feeling but a social institution","wordBankItems":["Vertrauen","ist","nicht","bloß","ein","Gefühl",",","sondern","eine","soziale","Institution","."],"correctAnswer":"Vertrauen ist nicht bloß ein Gefühl , sondern eine soziale Institution ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Hinweisen auf'' means?","options":["to point to","to indicate","to refer to","to highlight"],"correctAnswer":"to point to"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002a1',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss music and culture at B2","Use Musik und Kultur vocabulary","Talk about German musical tradition, classical heritage, and contemporary music scenes"],"explanation":{"intro":"Music and culture vocabulary covers Germany''s classical tradition, contemporary pop culture, and music''s social functions at B2.","culturalNote":"Musik und Kultur: Germany: extraordinary classical music heritage — Bach, Beethoven, Brahms, Wagner, Schubert (Austria), Händel, Schumann. Opera houses: Germany has more opera houses than any other country (~80). Festspiele (festivals): Bayreuther Festspiele (Wagner — pilgrimage for opera lovers), Salzburg (Austria), Berliner Philharmoniker (world-class). Contemporary: Neue Deutsche Welle (80s — Kraftwerk, Nena), Techno (Berlin Techno — Berghain, UNESCO intangible cultural heritage 2024!), Hip-Hop. Musikschule (music schools — widely accessible). GEMA (music rights organisation). Öffentlich-rechtlicher Rundfunk (public broadcasting — supporting culture — WDR, BR)."},"examples":[{"german":"Die klassische Musiktradition Deutschlands ist mehr als ein historisches Erbe — sie ist ein aktiv gepflegter Teil der nationalen Identität: Tausende Konzerthäuser, Musikschulen und Festivals halten eine Auseinandersetzung mit Beethoven und Bach lebendig, die in anderen Kulturen keine vergleichbare institutionelle Verwurzelung hat.","english":"Germany''s classical music tradition is more than a historical heritage — it is an actively cultivated part of national identity: thousands of concert halls, music schools, and festivals keep alive an engagement with Beethoven and Bach that in other cultures has no comparable institutional rootedness."},{"german":"Die Berliner Techno-Kultur veranschaulicht, wie Musik soziale Funktion übernimmt, die über reine Unterhaltung hinausgeht: Sie schafft temporäre Gemeinschaft jenseits sozialer Grenzen, verhandelt Körperlichkeit und Kontrollverlust und artikuliert implizit eine Gesellschaftskritik an der überperforierten Rationalität des Alltags.","english":"Berlin''s techno culture illustrates how music assumes a social function that goes beyond pure entertainment: it creates temporary community beyond social boundaries, negotiates corporeality and loss of control, and implicitly articulates a social critique of the over-perforated rationality of everyday life."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s classical music heritage, Berlin techno, and music''s social functions at B2."}}',
'{"items":[{"word":"gepflegt","translation":"cultivated","pronunciation":"geh-PFLAYKT","example":"Aktiv gepflegt."},{"word":"die Verwurzelung","translation":"rootedness","pronunciation":"dee fer-VOOR-tshe-loong","example":"Institutionelle Verwurzelung."},{"word":"veranschaulichen","translation":"to illustrate","pronunciation":"fer-AN-show-li-khen","example":"Soziale Funktion veranschaulichen."},{"word":"die Körperlichkeit","translation":"corporeality","pronunciation":"dee KÖR-per-likh-kyt","example":"Körperlichkeit verhandeln."},{"word":"implizit","translation":"implicitly","pronunciation":"im-PLI-tsit","example":"Implizit artikulieren."},{"word":"artikulieren","translation":"to articulate","pronunciation":"ar-ti-ku-LEER-en","example":"Kritik artikulieren."}]}',
'{"title":"Über X hinausgehen — to go beyond X (exceeding a category)","pattern":"etwas geht über X hinaus = something goes beyond X (über X hinausgehen = to go beyond X — separable: geht...über X hinaus; über + accusative marks what is exceeded)","explanation":"Über X hinausgehen = to go beyond X (separable: geht...hinaus; über + accusative). Musik übernimmt Funktionen, die über reine Unterhaltung hinausgehen = Music assumes functions that go beyond pure entertainment (über Unterhaltung hinausgehen). The pattern marks that something exceeds a given category or expectation. Compare: mehr als (more than — simpler), sich nicht auf X beschränken (not to be limited to X), weit über X hinausgehen (to go far beyond X — more emphatic), über das Ziel hinausschießen (to overshoot the mark — idiom, different meaning).","examples":[{"sentence":"Das Projekt geht weit über seine ursprünglichen Ziele hinaus.","translation":"The project goes far beyond its original goals."},{"sentence":"Sein Engagement geht über seine Pflichten hinaus.","translation":"His commitment goes beyond his duties."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Implizit'' means?","options":["implicitly","indirectly","tacitly","covertly"],"correctAnswer":"implicitly"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Germany''s classical music tradition is more than a historical heritage — it is an actively cultivated part of national identity: thousands of concert halls, music schools, and festivals keep alive an engagement with Beethoven and Bach that in other cultures has no comparable institutional rootedness.","options":["Die klassische Musiktradition Deutschlands ist mehr als ein historisches Erbe — sie ist ein aktiv gepflegter Teil der nationalen Identität: Tausende Konzerthäuser, Musikschulen und Festivals halten eine Auseinandersetzung mit Beethoven und Bach lebendig, die in anderen Kulturen keine vergleichbare institutionelle Verwurzelung hat.","Klassische Musik ist ein wichtiger Teil der deutschen Kultur und nationalen Identität.","Deutschland hat eine besonders lebendige klassische Musiktradition.","Beethoven und Bach sind ein zentraler Teil des deutschen kulturellen Erbes."],"correctAnswer":"Die klassische Musiktradition Deutschlands ist mehr als ein historisches Erbe — sie ist ein aktiv gepflegter Teil der nationalen Identität: Tausende Konzerthäuser, Musikschulen und Festivals halten eine Auseinandersetzung mit Beethoven und Bach lebendig, die in anderen Kulturen keine vergleichbare institutionelle Verwurzelung hat."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Projekt geht weit über seine ursprünglichen Ziele ___.","options":["hinaus","hinweg","hindurch","hinauf"],"correctAnswer":"hinaus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: His commitment goes beyond his duties","wordBankItems":["Sein","Engagement","geht","über","seine","Pflichten","hinaus","."],"correctAnswer":"Sein Engagement geht über seine Pflichten hinaus ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Veranschaulichen'' means?","options":["to illustrate","to demonstrate","to show","to exemplify"],"correctAnswer":"to illustrate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002a2',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss film and cinema at B2","Use Film und Kino vocabulary","Talk about German cinema tradition and contemporary film industry"],"explanation":{"intro":"Film and cinema vocabulary covers German cinema history, New German Cinema, and contemporary film at B2.","culturalNote":"Film und Kino: Germany''s cinema history: Expressionism (Das Cabinet des Dr. Caligari 1920, Nosferatu 1922), Fritz Lang (Metropolis 1927, M 1931). Under NS: Riefenstahl''s Triumph des Willens (1935 — propaganda). Post-WWII: Trümmerfilme (rubble films — about reconstruction). Neuer Deutscher Film (New German Cinema — 1960s-80s): Fassbinder, Herzog, Wenders, Schlöndorff (Die Blechtrommel — 1979 Oscar), Bergmann (German). Contemporary: Deutsche Filmakademie, Berlinale (Berlin International Film Festival — one of the ''Big Five''). Filmförderung (film funding — FFA, state funding). Key: Run Lola Run (1998), Good Bye Lenin! (2003), Das Leben der Anderen (The Lives of Others — 2006 Oscar)."},"examples":[{"german":"Das deutsche Kino des Expressionismus nutzte Bildsprache als direktes Ausdrucksmittel innerer Zustände: Verzerrte Geometrien, extreme Schatten und entstellte Figuren externalisierten Angst, Machtwahn und gesellschaftliche Deformation auf eine Weise, die den psychologischen Realismus des frühen Hollywood radikal kontrastierte.","english":"German expressionist cinema used visual language as a direct means of expression of inner states: distorted geometries, extreme shadows, and distorted figures externalised fear, megalomania, and social deformation in a way that radically contrasted with the psychological realism of early Hollywood."},{"german":"Der Neue Deutsche Film der 1970er Jahre war ein politisch-ästhetisches Projekt: Er stellte das konventionelle Unterhaltungskino infrage, verweigerte die Identifikationsangebote des Mainstreams und konfrontierte das Publikum mit der unverarbeiteten NS-Vergangenheit — ein Kino des Unbequemseins.","english":"New German Cinema of the 1970s was a political-aesthetic project: it questioned conventional entertainment cinema, refused the identification offers of the mainstream, and confronted the audience with the unprocessed Nazi past — a cinema of discomfort."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss German Expressionism, New German Cinema, and contemporary German film at B2."}}',
'{"items":[{"word":"die Bildsprache","translation":"visual language","pronunciation":"dee BILD-shprah-kheh","example":"Filmische Bildsprache."},{"word":"externalisieren","translation":"to externalise","pronunciation":"ex-ter-nah-li-ZEER-en","example":"Angst externalisieren."},{"word":"der Machtwahn","translation":"megalomania","pronunciation":"dayr MAKHT-vahn","example":"Machtwahn darstellen."},{"word":"verweigern","translation":"to refuse/deny","pronunciation":"fer-VY-gern","example":"Identifikation verweigern."},{"word":"das Unbehagen","translation":"discomfort","pronunciation":"dahs oon-beh-HAH-gen","example":"Kino des Unbehagens."},{"word":"konfrontieren mit","translation":"to confront with","pronunciation":"kon-fron-TEER-en mit","example":"Mit Vergangenheit konfrontieren."}]}',
'{"title":"Infrage stellen vs. auf die Probe stellen — to question vs. to put to the test","pattern":"etwas infrage stellen = to call into question (stellen + infrage/in Frage = to question — challenges the assumption); etwas auf die Probe stellen = to put to the test (stellen + auf die Probe = test whether it holds up)","explanation":"Two stellen phrases with different meanings: (1) infrage stellen = to call into question (challenge or doubt the validity of something). Der Film stellt das konventionelle Kino infrage = The film questions conventional cinema. (2) auf die Probe stellen = to put to the test (test whether something is as claimed/functional). Die Krise hat die Freundschaft auf die Probe gestellt = The crisis put the friendship to the test. Important: infrage stellen = conceptual challenge (''is this valid?''); auf die Probe stellen = empirical test (''does this hold up?''). Do not confuse: infrage kommen = to come into question, to be possible (different meaning again).","examples":[{"sentence":"Die Forschung stellt verbreitete Annahmen infrage.","translation":"The research calls widespread assumptions into question."},{"sentence":"Die Auseinandersetzung hat unsere Zusammenarbeit auf die Probe gestellt.","translation":"The dispute put our collaboration to the test."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Externalisieren'' means?","options":["to externalise","to project","to express outwardly","to manifest externally"],"correctAnswer":"to externalise"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"New German Cinema of the 1970s was a political-aesthetic project: it questioned conventional entertainment cinema, refused the identification offers of the mainstream, and confronted the audience with the unprocessed Nazi past — a cinema of discomfort.","options":["Der Neue Deutsche Film der 1970er Jahre war ein politisch-ästhetisches Projekt: Er stellte das konventionelle Unterhaltungskino infrage, verweigerte die Identifikationsangebote des Mainstreams und konfrontierte das Publikum mit der unverarbeiteten NS-Vergangenheit — ein Kino des Unbequemseins.","Der Neue Deutsche Film wollte Kino politisieren und die NS-Vergangenheit aufarbeiten.","Regisseure wie Fassbinder und Herzog machten ein bewusst unbequemes, kritisches Kino.","Das neue deutsche Kino der 70er Jahre lehnte Hollywood-Konventionen ab."],"correctAnswer":"Der Neue Deutsche Film der 1970er Jahre war ein politisch-ästhetisches Projekt: Er stellte das konventionelle Unterhaltungskino infrage, verweigerte die Identifikationsangebote des Mainstreams und konfrontierte das Publikum mit der unverarbeiteten NS-Vergangenheit — ein Kino des Unbequemseins."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Forschung stellt verbreitete Annahmen ___.","options":["infrage","in Frage","in Zweifel","zur Diskussion"],"correctAnswer":"infrage"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The dispute put our collaboration to the test","wordBankItems":["Die","Auseinandersetzung","hat","unsere","Zusammenarbeit","auf","die","Probe","gestellt","."],"correctAnswer":"Die Auseinandersetzung hat unsere Zusammenarbeit auf die Probe gestellt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Verweigern'' means?","options":["to refuse/deny","to reject","to decline","to withhold"],"correctAnswer":"to refuse/deny"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002a3',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss architecture and space at B2","Use Architektur und Raum vocabulary","Talk about German architectural history and contemporary urban design"],"explanation":{"intro":"Architecture and space vocabulary covers German architectural traditions, Bauhaus heritage, and urban design at B2.","culturalNote":"Architektur und Raum: Germany''s architectural heritage: Neoclassicism (Schinkel — Altes Museum Berlin), Wilhelminismus (Gründerzeit — historicist), Jugendstil (Art Nouveau), Bauhaus (1919 Weimar/Dessau/Berlin — Walter Gropius — functionalism, design modernism — ''form follows function''). NS architecture: Albert Speer (gigantism, intimidation). Post-war: reconstruction, Wirtschaftswunder modern, Organic and postmodern (Hans Scharoun — Berliner Philharmonie). Reunification: Potsdamer Platz redesign, Berlin as laboratory. Denkmalschutz (listed building protection). Key contemporary debates: Autogerechte Stadt (car-centric city) vs. Fahrradstadt (cycling city)."},"examples":[{"german":"Das Bauhaus-Konzept formulierte eine radikale Synthese von Kunst und Handwerk: Es lehnte die Trennung zwischen angewandter und reiner Kunst ab und setzte auf die gesellschaftliche Funktion des Designs — ein Gegenentwurf zu einer Dekorations- und Repräsentationsarchitektur, die Form von Funktion und Zweck entkoppelte.","english":"The Bauhaus concept formulated a radical synthesis of art and craft: it rejected the separation between applied and pure art and relied on the social function of design — a counter-concept to a decorative and representational architecture that decoupled form from function and purpose."},{"german":"Gebaute Umwelt ist nie neutral: Raumplanung und Architektur spiegeln gesellschaftliche Machtverhältnisse und Wertvorstellungen wider — Fußgängerzonen oder Autobahnen, öffentliche Parks oder Privatgebäude zeigen, wessen Ansprüche an urbanen Raum privilegiert werden.","english":"The built environment is never neutral: spatial planning and architecture mirror societal power relations and values — pedestrian zones or motorways, public parks or private buildings show whose claims to urban space are privileged."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the Bauhaus, German architectural history, and built environment as power at B2."}}',
'{"items":[{"word":"die Synthese","translation":"synthesis","pronunciation":"dee ZÜN-teh-zeh","example":"Radikale Synthese."},{"word":"der Gegenentwurf","translation":"counter-concept","pronunciation":"dayr GAY-gen-ent-vooorf","example":"Gegenentwurf formulieren."},{"word":"entkoppeln","translation":"to decouple","pronunciation":"ent-KOP-eln","example":"Form von Funktion entkoppeln."},{"word":"die Raumplanung","translation":"spatial planning","pronunciation":"dee ROWM-plah-noong","example":"Raumplanung und Architektur."},{"word":"widerspiegeln","translation":"to mirror/reflect","pronunciation":"VEE-der-shpee-geln","example":"Machtverhältnisse widerspiegeln."},{"word":"privilegiert","translation":"privileged","pronunciation":"pri-vi-leh-GEERT","example":"Ansprüche privilegiert."}]}',
'{"title":"Ablehnen + Gerundiv construction — rejecting a separation","pattern":"etwas ablehnen = to reject something (ablehnen = to reject, decline — separable: lehnt...ab). Often followed by the THING rejected as a noun: die Trennung ablehnen (to reject the separation). Key pattern: Es lehnte X ab und setzte auf Y (It rejected X and relied on Y).","explanation":"Ablehnen = to reject (separable: lehnt...ab). Das Bauhaus lehnte die Trennung zwischen X und Y ab = The Bauhaus rejected the separation between X and Y. Common structure in argumentation: etwas ablehnen und stattdessen auf Y setzen (to reject X and instead rely on/bet on Y). Note: ablehnen vs. abweisen (to refuse/turn away — of requests), verwerfen (to discard/reject an idea after evaluation — stronger), zurückweisen (to reject/rebuff — of criticism), sich entziehen (to resist/evade). Setzen auf = to rely on, bet on, pin hopes on.","examples":[{"sentence":"Die Reform lehnte das alte Modell ab und setzte auf einen neuen Ansatz.","translation":"The reform rejected the old model and relied on a new approach."},{"sentence":"Er lehnte eine Kompromisslösung ab.","translation":"He rejected a compromise solution."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Synthese'' means?","options":["synthesis","fusion","combination","merger"],"correctAnswer":"synthesis"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Bauhaus concept formulated a radical synthesis of art and craft: it rejected the separation between applied and pure art and relied on the social function of design — a counter-concept to a decorative and representational architecture that decoupled form from function and purpose.","options":["Das Bauhaus-Konzept formulierte eine radikale Synthese von Kunst und Handwerk: Es lehnte die Trennung zwischen angewandter und reiner Kunst ab und setzte auf die gesellschaftliche Funktion des Designs — ein Gegenentwurf zu einer Dekorations- und Repräsentationsarchitektur, die Form von Funktion und Zweck entkoppelte.","Bauhaus verband Kunst und Handwerk und stellte Design in den Dienst der Gesellschaft.","Das Bauhaus war eine radikale Designschule, die Form und Funktion vereinte.","Bauhaus lehnte dekorative Kunst ab und entwickelte funktionales Design."],"correctAnswer":"Das Bauhaus-Konzept formulierte eine radikale Synthese von Kunst und Handwerk: Es lehnte die Trennung zwischen angewandter und reiner Kunst ab und setzte auf die gesellschaftliche Funktion des Designs — ein Gegenentwurf zu einer Dekorations- und Repräsentationsarchitektur, die Form von Funktion und Zweck entkoppelte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Reform lehnte das alte Modell ab und setzte auf einen neuen ___.","options":["Ansatz","Weg","Kurs","Plan"],"correctAnswer":"Ansatz"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He rejected a compromise solution","wordBankItems":["Er","lehnte","eine","Kompromisslösung","ab","."],"correctAnswer":"Er lehnte eine Kompromisslösung ab ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Widerspiegeln'' means?","options":["to mirror/reflect","to represent","to show","to depict"],"correctAnswer":"to mirror/reflect"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002a4',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss philosophy of everyday life at B2","Use Philosophie des Alltags vocabulary","Talk about phenomenology, everyday experience, and philosophical anthropology"],"explanation":{"intro":"Philosophy of everyday life vocabulary covers phenomenology, lifeworld, and German philosophical traditions around lived experience at B2.","culturalNote":"Philosophie des Alltags: Germany is a philosophical powerhouse: Kant (Critique of Pure Reason — Enlightenment), Hegel (dialectics — Aufhebung), Marx (historical materialism), Nietzsche (will to power, death of God), Husserl (phenomenology — Lebenswelt — lifeworld), Heidegger (Being and Time — Dasein, thrownness, Alltäglichkeit), Hannah Arendt (public realm, totalitarianism), Jürgen Habermas (communicative action, public sphere). Key concepts: Lebenswelt (lifeworld), Dasein (being-there), Alltäglichkeit (everydayness), Intersubjektivität (intersubjectivity), Praxis (practice — Marx/Aristotle)."},"examples":[{"german":"Heideggers Begriff der ''Alltäglichkeit'' deutet das Alltägliche nicht als triviales Terrain, sondern als den ursprünglichen Modus des In-der-Welt-Seins: Werkzeug, Sprache und Mitmensch sind nicht abstrakte Objekte unserer Erkenntnis, sondern zuhandene Bestandteile eines gelebten Weltzusammenhangs.","english":"Heidegger''s concept of ''everydayness'' interprets the everyday not as trivial terrain, but as the originary mode of being-in-the-world: tool, language, and fellow human are not abstract objects of our cognition, but ready-to-hand constituents of a lived contextual world."},{"german":"Die Lebenswelt im Sinne Husserls bezeichnet die vorwissenschaftliche Erfahrungswelt, in der wir immer schon leben, bevor wir auf sie wissenschaftlich reflektieren: Sie ist der unhinterfragbare Boden aller Erkenntnis — und damit zugleich das, was durch wissenschaftliche Abstraktion stets in Gefahr gerät, vergessen zu werden.","english":"The lifeworld in Husserl''s sense denotes the pre-scientific experiential world in which we always already live before we reflect on it scientifically: it is the unquestionable ground of all knowledge — and thus at the same time what is always in danger of being forgotten through scientific abstraction."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Heidegger''s everydayness, Husserl''s lifeworld, and German phenomenology at B2."}}',
'{"items":[{"word":"ursprünglich","translation":"originary/original","pronunciation":"oor-SHPRÜNG-likh","example":"Ursprünglicher Modus."},{"word":"zuhandenheit","translation":"ready-to-handness","pronunciation":"TSOO-hahn-den-hyt","example":"Zuhandene Bestandteile."},{"word":"gelebt","translation":"lived","pronunciation":"geh-LAYBT","example":"Gelebte Erfahrung."},{"word":"vorwissenschaftlich","translation":"pre-scientific","pronunciation":"FOR-vis-en-shaft-likh","example":"Vorwissenschaftliche Erfahrung."},{"word":"unhinterfragbar","translation":"unquestionable","pronunciation":"oon-HIN-ter-frahk-bahr","example":"Unhinterfragbarer Boden."},{"word":"bezeichnen","translation":"to denote/designate","pronunciation":"beh-TSYKH-nen","example":"Die Lebenswelt bezeichnet..."}]}',
'{"title":"Immer schon — always already (the pre-reflective background)","pattern":"etwas ist/tun wir immer schon = something is/we always already do X (immer schon = always already — a key phenomenological phrase: we are always ALREADY in the state before explicit reflection; not a tautology — marks the pre-reflective background)","explanation":"Immer schon = always already (a translation of the German phenomenological phrase — marking that something is already the case before we consciously attend to it). Wir leben immer schon in der Lebenswelt = We always already live in the lifeworld (before any scientific or reflective act — it is the unchosen background). Not just ''always'' (immer) but ''always prior to reflection'' (schon = already). This is different from ''immer noch'' (still) — schon here means the prior-ness of the state. Compare: von vornherein (from the outset), a priori (before experience — more Kantian), bereits (already — simpler, temporal).","examples":[{"sentence":"Wir befinden uns immer schon in Sprache — wir werden nicht in eine sprachlose Welt geboren.","translation":"We are always already in language — we are not born into a speechless world."},{"sentence":"Das Kind ist immer schon sozial eingebettet, bevor es über Sozialität nachdenkt.","translation":"The child is always already socially embedded before it thinks about sociality."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Vorwissenschaftlich'' means?","options":["pre-scientific","non-scientific","unscientific","before science"],"correctAnswer":"pre-scientific"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The lifeworld in Husserl''s sense denotes the pre-scientific experiential world in which we always already live before we reflect on it scientifically: it is the unquestionable ground of all knowledge — and thus at the same time what is always in danger of being forgotten through scientific abstraction.","options":["Die Lebenswelt im Sinne Husserls bezeichnet die vorwissenschaftliche Erfahrungswelt, in der wir immer schon leben, bevor wir auf sie wissenschaftlich reflektieren: Sie ist der unhinterfragbare Boden aller Erkenntnis — und damit zugleich das, was durch wissenschaftliche Abstraktion stets in Gefahr gerät, vergessen zu werden.","Husserl nennt die Alltagswelt ''Lebenswelt'' — sie ist die Grundlage aller Erkenntnis.","Die Lebenswelt ist das, was wir erleben, bevor wir wissenschaftlich darüber nachdenken.","Wissenschaft baut auf der Lebenswelt auf, die sie oft vergisst."],"correctAnswer":"Die Lebenswelt im Sinne Husserls bezeichnet die vorwissenschaftliche Erfahrungswelt, in der wir immer schon leben, bevor wir auf sie wissenschaftlich reflektieren: Sie ist der unhinterfragbare Boden aller Erkenntnis — und damit zugleich das, was durch wissenschaftliche Abstraktion stets in Gefahr gerät, vergessen zu werden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wir befinden uns immer schon in Sprache — wir werden nicht in eine sprachlose Welt ___.","options":["geboren","hineingeworfen","eingeführt","gestellt"],"correctAnswer":"geboren"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The child is always already socially embedded before it thinks about sociality","wordBankItems":["Das","Kind","ist","immer","schon","sozial","eingebettet",",","bevor","es","über","Sozialität","nachdenkt","."],"correctAnswer":"Das Kind ist immer schon sozial eingebettet , bevor es über Sozialität nachdenkt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bezeichnen'' means?","options":["to denote/designate","to label","to name","to term"],"correctAnswer":"to denote/designate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002a5',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss ethics and morality at B2","Use Ethik und Moral vocabulary","Talk about moral frameworks, applied ethics, and Germany''s ethical debates"],"explanation":{"intro":"Ethics and morality vocabulary covers moral philosophy frameworks, applied ethics, and Germany''s ethical culture at B2.","culturalNote":"Ethik und Moral: Key frameworks: Deontologie (Kant — categorical imperative — ''handle nur nach derjenigen Maxime...''), Utilitarismus (Bentham/Mill — greatest happiness principle), Tugendethik (virtue ethics — Aristotle — character), Diskursethik (Habermas — communicative reason — consensus). Key German applied ethics: Bioethik (bioethics — stem cells, euthanasia — Sterbehilfe debate — Germany has complex history given NS euthanasia), Tierschutz (animal welfare — strong German tradition), KI-Ethik (AI ethics). Ethikrat (German Ethics Council — advising Bundestag). Moral und Recht (morality and law — not identical: Hart/Dworkin debate). Key distinction: Ethik = systematic study of morality; Moral = actual moral norms and practices."},"examples":[{"german":"Der kategorische Imperativ Kants fordert, nur nach Maximen zu handeln, die man zugleich als allgemeines Gesetz wollen kann — ein Universalisierungstest, der Eigeninteresse und Sonderrechte durch das Prinzip der formalen Gleichbehandlung begrenzt und moralisches Handeln von Konsequenzen entkoppelt.","english":"Kant''s categorical imperative demands to act only according to maxims that one can at the same time will as a universal law — a universalisation test that limits self-interest and special rights through the principle of formal equal treatment and decouples moral action from consequences."},{"german":"Die Diskursethik Habermas'' verbindet moralische Geltungsansprüche mit dem Verfahren des herrschaftsfreien Diskurses: Eine Norm ist moralisch gültig, wenn alle Betroffenen ihr in einem idealen Gespräch zustimmen würden — ein kontrafaktisches Modell, das reale Diskurse an einem normativen Ideal messen lässt.","english":"Habermas'' discourse ethics links moral claims to validity with the procedure of domination-free discourse: a norm is morally valid if all those affected would agree to it in an ideal conversation — a counterfactual model that allows real discourses to be measured against a normative ideal."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Kant''s categorical imperative, Habermas'' discourse ethics, and applied ethics at B2."}}',
'{"items":[{"word":"der kategorische Imperativ","translation":"categorical imperative","pronunciation":"dayr kah-teh-GOH-ri-sheh im-peh-rah-TEEF","example":"Kategorischer Imperativ."},{"word":"die Maxime","translation":"maxim","pronunciation":"dee mak-SEE-meh","example":"Nach Maximen handeln."},{"word":"die Universalisierung","translation":"universalisation","pronunciation":"dee oo-ni-ver-zah-li-ZEE-roong","example":"Universalisierungstest."},{"word":"kontrafaktisch","translation":"counterfactual","pronunciation":"kon-trah-FAK-tish","example":"Kontrafaktisches Modell."},{"word":"die Gültigkeit","translation":"validity","pronunciation":"dee GÜL-tikh-kyt","example":"Moralische Gültigkeit."},{"word":"herrschaftsfrei","translation":"domination-free","pronunciation":"HER-shaft-sfry","example":"Herrschaftsfreier Diskurs."}]}',
'{"title":"An einem normativen Ideal messen — to measure against a normative ideal","pattern":"etwas an einem Ideal messen = to measure something against an ideal (messen + an + dative = to measure against; jemanden/etwas an seinen eigenen Maßstäben messen = to hold to their own standards)","explanation":"An X messen = to measure against X (messen + an + dative). Reale Diskurse an einem normativen Ideal messen = to measure real discourses against a normative ideal. The phrase implies a gap between is and ought — the actual is evaluated against the standard. Common: an Maßstäben messen (to measure by standards), sich an X messen (to measure oneself against X — competitive), mit zweierlei Maß messen (to apply double standards — idiom). Also: messen lassen = to allow oneself to be measured (passive reflex). Compare: bewerten an (to evaluate by), beurteilen nach (to judge according to).","examples":[{"sentence":"Die Praxis muss sich an den eigenen Versprechen messen lassen.","translation":"Practice must allow itself to be measured against its own promises."},{"sentence":"Wir messen Institutionen an ihren erklärten Werten.","translation":"We measure institutions against their declared values."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Kontrafaktisch'' means?","options":["counterfactual","hypothetical","contrary to fact","theoretical"],"correctAnswer":"counterfactual"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Kant''s categorical imperative demands to act only according to maxims that one can at the same time will as a universal law — a universalisation test that limits self-interest and special rights through the principle of formal equal treatment and decouples moral action from consequences.","options":["Der kategorische Imperativ Kants fordert, nur nach Maximen zu handeln, die man zugleich als allgemeines Gesetz wollen kann — ein Universalisierungstest, der Eigeninteresse und Sonderrechte durch das Prinzip der formalen Gleichbehandlung begrenzt und moralisches Handeln von Konsequenzen entkoppelt.","Kants Imperativ verlangt, so zu handeln, wie man es von allen erwarten würde.","Kant fordert universell anwendbare Moral, nicht situationsabhängige.","Moralisch ist, was als allgemeines Gesetz taugt."],"correctAnswer":"Der kategorische Imperativ Kants fordert, nur nach Maximen zu handeln, die man zugleich als allgemeines Gesetz wollen kann — ein Universalisierungstest, der Eigeninteresse und Sonderrechte durch das Prinzip der formalen Gleichbehandlung begrenzt und moralisches Handeln von Konsequenzen entkoppelt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Praxis muss sich an den eigenen Versprechen messen ___.","options":["lassen","müssen","können","sollen"],"correctAnswer":"lassen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We measure institutions against their declared values","wordBankItems":["Wir","messen","Institutionen","an","ihren","erklärten","Werten","."],"correctAnswer":"Wir messen Institutionen an ihren erklärten Werten ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Herrschaftsfrei'' means?","options":["domination-free","power-free","authority-free","coercion-free"],"correctAnswer":"domination-free"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002a6',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss religion and secularism at B2","Use Religion und Säkularismus vocabulary","Talk about Germany''s religious landscape, church and state, and secularisation"],"explanation":{"intro":"Religion and secularism vocabulary covers Germany''s religious landscape, state-church relations, and secularisation debates at B2.","culturalNote":"Religion und Säkularismus: Germany: historically divided (north Protestant, south Catholic — Reformation — Luther — 1517). Post-reunification: German secular east (former DDR — Atheismus) + religious west. Religionszugehörigkeit (religious affiliation): ~24% Catholic, ~22% Protestant (EKD), ~5-6% Muslim, ~40%+ konfessionslos (unaffiliated). Kirchensteuer (church tax — 8-9% income tax surcharge — voluntary via Kirchenaustritt). Religionsunterricht (religious education in public schools — not compulsory). State-church separation (Art. 140 GG) but no strict laïcité (like France) — cooperative model (Körperschaften des öffentlichen Rechts). Debatten: Kopftuch (headscarf — teacher neutrality debates), Blasphemie (§166 StGB), Islam als Teil Deutschlands (Islam as part of Germany — contested)."},"examples":[{"german":"Das deutsche Verhältnis zwischen Staat und Kirche ist kein Trennungs-, sondern ein Kooperationsmodell: Der Staat bleibt weltanschaulich neutral, gewährt den Religionsgemeinschaften aber besondere Rechtsstellung und Kooperationsrechte — eine Balance, die das Grundgesetz aus dem Weimarer Kirchenkompromiss übernommen hat.","english":"The German relationship between state and church is not a separation but a cooperation model: the state remains worldview-neutral, but grants the religious communities a special legal status and cooperation rights — a balance that the Basic Law adopted from the Weimar church compromise."},{"german":"Säkularisierung bedeutet nicht das Ende von Religiosität, sondern deren Transformation: Institutionelle Bindungen schwinden, während spirituelle Sinnsuche individualisiert, pluralisiert und von konfessionellen Grenzen befreit weitergeführt wird — ein Befund, der die These vom Absterben der Religion widerlegt.","english":"Secularisation does not mean the end of religiosity, but its transformation: institutional ties wane, while the spiritual search for meaning continues, individualised, pluralised, and freed from confessional boundaries — a finding that refutes the thesis of the extinction of religion."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s church-state model, church tax, and secularisation at B2."}}',
'{"items":[{"word":"weltanschaulich","translation":"worldview","pronunciation":"VELT-an-show-likh","example":"Weltanschaulich neutral."},{"word":"die Rechtsstellung","translation":"legal status","pronunciation":"dee REKHTS-shtel-oong","example":"Besondere Rechtsstellung."},{"word":"die Religiosität","translation":"religiosity","pronunciation":"dee reh-li-gyo-zi-TÄT","example":"Religiöse Religiosität."},{"word":"schwinden","translation":"to wane/diminish","pronunciation":"SHVIN-den","example":"Bindungen schwinden."},{"word":"widerlegen","translation":"to refute","pronunciation":"VEE-der-lay-gen","example":"These widerlegen."},{"word":"das Absterben","translation":"extinction/dying out","pronunciation":"dahs AP-shter-ben","example":"Absterben der Religion."}]}',
'{"title":"Den Befund, dass X, widerlegen — to refute the finding that X","pattern":"den Befund widerlegen, dass X = to refute the finding/thesis that X (widerlegen = to refute — takes accusative object; dass-clause can substitute the object: widerlegt die These vom X)","explanation":"Widerlegen = to refute, to disprove (takes accusative). Den Befund/die These/die Behauptung widerlegen = to refute the finding/thesis/claim. Ein Befund, der die These vom Absterben der Religion widerlegt = A finding that refutes the thesis of the extinction of religion. Widerlegen is stronger than in Frage stellen (to call into question) — it implies proof of the contrary. Die These vom X (the thesis of X) = the claim that X holds. Compare: widersprechen + dative (to contradict — weaker), entkräften (to weaken/undermine an argument — partial refutation), belegen (to prove — opposite direction).","examples":[{"sentence":"Die Studie widerlegt die Annahme, dass Reichtum automatisch glücklich macht.","translation":"The study refutes the assumption that wealth automatically makes one happy."},{"sentence":"Die Ergebnisse widerlegen die ursprüngliche Hypothese.","translation":"The results refute the original hypothesis."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Weltanschaulich'' means?","options":["worldview (adjective)","ideological","philosophical","value-based"],"correctAnswer":"worldview (adjective)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Secularisation does not mean the end of religiosity, but its transformation: institutional ties wane, while the spiritual search for meaning continues, individualised, pluralised, and freed from confessional boundaries — a finding that refutes the thesis of the extinction of religion.","options":["Säkularisierung bedeutet nicht das Ende von Religiosität, sondern deren Transformation: Institutionelle Bindungen schwinden, während spirituelle Sinnsuche individualisiert, pluralisiert und von konfessionellen Grenzen befreit weitergeführt wird — ein Befund, der die These vom Absterben der Religion widerlegt.","Säkularisierung bedeutet nicht weniger Religion, sondern andere Religion.","Auch in säkularen Gesellschaften suchen Menschen nach spiritueller Bedeutung.","Religiosität verschwindet nicht, sondern verändert ihre Form."],"correctAnswer":"Säkularisierung bedeutet nicht das Ende von Religiosität, sondern deren Transformation: Institutionelle Bindungen schwinden, während spirituelle Sinnsuche individualisiert, pluralisiert und von konfessionellen Grenzen befreit weitergeführt wird — ein Befund, der die These vom Absterben der Religion widerlegt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Studie widerlegt die Annahme, dass Reichtum automatisch glücklich ___.","options":["macht","erzeugt","schafft","bewirkt"],"correctAnswer":"macht"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The results refute the original hypothesis","wordBankItems":["Die","Ergebnisse","widerlegen","die","ursprüngliche","Hypothese","."],"correctAnswer":"Die Ergebnisse widerlegen die ursprüngliche Hypothese ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Schwinden'' means?","options":["to wane/diminish","to disappear","to decrease","to fade"],"correctAnswer":"to wane/diminish"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002a7',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss science and society at B2","Use Wissenschaft und Gesellschaft vocabulary","Talk about the social role of science, trust in expertise, and research culture"],"explanation":{"intro":"Science and society vocabulary covers the social contract of science, trust in expertise, and Germany''s research culture at B2.","culturalNote":"Wissenschaft und Gesellschaft: Germany: research-intensive economy (R&D spending ~3.1% of GDP — above OECD average). Key institutions: Max-Planck-Gesellschaft (basic research), Fraunhofer-Gesellschaft (applied research), Helmholtz (large-scale research), Leibniz (cross-disciplinary). Hochschulfinanzierung (university funding — Exzellenzinitiative/Exzellenzstrategie — competing elite universities — ''Ivy League'' ambitions). Nobelpreisträger (Nobel laureates — Germany top 3 globally historically). Wissenschaftsfreiheit (academic freedom — Art. 5 III GG). Post-COVID: Wissenschaftsskepsis (science scepticism), querdenken movement. Open Science movement. Drittmittel (third-party funding) — dependence on industry. Peer review."},"examples":[{"german":"Wissenschaft genießt demokratische Legitimation nur, wenn sie transparent, kritisierbar und rechenschaftspflichtig ist: Peer-Review, Replikation und open access sind nicht nur methodische Gütestandards, sondern Mechanismen der sozialen Kontrolle, die Wissenschaft als Institution in demokratische Gesellschaft einbetten.","english":"Science enjoys democratic legitimation only when it is transparent, criticisable, and accountable: peer review, replication, and open access are not only methodological quality standards, but mechanisms of social control that embed science as an institution in democratic society."},{"german":"Das Vertrauen in Wissenschaft ist eine gesellschaftliche Ressource, die nicht beliebig strapaziert werden kann: Wenn politische Akteure wissenschaftliche Erkenntnisse selektiv für ihre Zwecke instrumentalisieren, untergraben sie langfristig genau die epistemische Autorität, auf die sie sich kurzfristig berufen.","english":"Trust in science is a societal resource that cannot be strained arbitrarily: when political actors selectively instrumentalise scientific findings for their purposes, they undermine in the long run precisely the epistemic authority on which they rely in the short term."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s research institutions, science and democracy, and trust in expertise at B2."}}',
'{"items":[{"word":"rechenschaftspflichtig","translation":"accountable","pronunciation":"REH-khen-shaft-pflikhtikh","example":"Rechenschaftspflichtig sein."},{"word":"die Replikation","translation":"replication","pronunciation":"dee rep-li-kah-TSYOHN","example":"Wissenschaftliche Replikation."},{"word":"einbetten","translation":"to embed","pronunciation":"YN-bet-en","example":"In Gesellschaft einbetten."},{"word":"strapazieren","translation":"to strain","pronunciation":"shtrah-pah-TSEER-en","example":"Vertrauen strapazieren."},{"word":"instrumentalisieren","translation":"to instrumentalise","pronunciation":"in-stru-men-tah-li-ZEER-en","example":"Erkenntnisse instrumentalisieren."},{"word":"epistemisch","translation":"epistemic","pronunciation":"eh-pis-TAY-mish","example":"Epistemische Autorität."}]}',
'{"title":"Sich kurzfristig auf X berufen vs. X langfristig untergraben — short-term appeal vs. long-term undermining","pattern":"sich auf X berufen = to appeal to / invoke X (berufen auf + accusative — reflexive: sich berufen auf). X untergraben = to undermine X. The tension: claiming legitimacy from X while simultaneously destroying it.","explanation":"Sich auf X berufen = to appeal to X, to invoke X, to cite X as authority (separable reflexive: beruft sich...auf). Auf epistemische Autorität berufen = to invoke epistemic authority. The pattern kurzfristig auf X berufen (short-term appeal) while X untergraben (undermining X) = using something while destroying it. Berufen auf vs. verweisen auf (to refer to — more neutral citation), vertrauen auf (to trust in), sich stützen auf (to rely on). Untergraben = to undermine (literally: to dig under — structurally weaken).","examples":[{"sentence":"Sie beriefen sich auf die Wissenschaft, aber untergruben zugleich die Unabhängigkeit der Forscher.","translation":"They invoked science, but at the same time undermined the independence of researchers."},{"sentence":"Er beruft sich auf Tradition, weicht aber von ihr ab.","translation":"He appeals to tradition, but departs from it."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Epistemisch'' means?","options":["epistemic","cognitive","knowledge-related","intellectual"],"correctAnswer":"epistemic"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Trust in science is a societal resource that cannot be strained arbitrarily: when political actors selectively instrumentalise scientific findings for their purposes, they undermine in the long run precisely the epistemic authority on which they rely in the short term.","options":["Das Vertrauen in Wissenschaft ist eine gesellschaftliche Ressource, die nicht beliebig strapaziert werden kann: Wenn politische Akteure wissenschaftliche Erkenntnisse selektiv für ihre Zwecke instrumentalisieren, untergraben sie langfristig genau die epistemische Autorität, auf die sie sich kurzfristig berufen.","Politiker, die Wissenschaft für ihre Zwecke benutzen, gefährden das Vertrauen in sie.","Vertrauen in Wissenschaft ist fragil und kann durch Instrumentalisierung zerstört werden.","Wissenschaft braucht politische Unabhängigkeit, damit ihr Vertrauen erhalten bleibt."],"correctAnswer":"Das Vertrauen in Wissenschaft ist eine gesellschaftliche Ressource, die nicht beliebig strapaziert werden kann: Wenn politische Akteure wissenschaftliche Erkenntnisse selektiv für ihre Zwecke instrumentalisieren, untergraben sie langfristig genau die epistemische Autorität, auf die sie sich kurzfristig berufen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sie beriefen sich auf die Wissenschaft, aber untergruben zugleich die Unabhängigkeit der ___.","options":["Forscher","Wissenschaftler","Experten","Fachleute"],"correctAnswer":"Forscher"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He appeals to tradition but departs from it","wordBankItems":["Er","beruft","sich","auf","Tradition",",","weicht","aber","von","ihr","ab","."],"correctAnswer":"Er beruft sich auf Tradition , weicht aber von ihr ab ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Instrumentalisieren'' means?","options":["to instrumentalise","to exploit","to use for purposes","to weaponise"],"correctAnswer":"to instrumentalise"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002a8',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the consequences of technology at B2","Use Technologiefolgen vocabulary","Talk about technology assessment, digital transformation, and unintended consequences"],"explanation":{"intro":"Technology consequences vocabulary covers technology assessment, unintended effects, and Germany''s approach to tech regulation at B2.","culturalNote":"Technologiefolgen: Germany: technology-ambivalent — strong industrial innovation but cautious about social/ethical consequences. Key institution: Büro für Technikfolgen-Abschätzung beim Deutschen Bundestag (TAB — Technology Assessment Office). Vorsorgeprinzip (precautionary principle — EU hallmark: ''if there is risk, restrict'') vs. US innovation-first. Key issues: Datenschutz (GDPR — strongest data protection globally), Künstliche Intelligenz (AI Act — EU, 2024), Autonome Systeme (autonomous systems — killer robots), Biotechnologie (GMO, CRISPR — Germany sceptical), Energiewende (tech for sustainability). Digitale Infrastruktur (Germany''s slow broadband — embarrassing for tech nation). Luddismus (Luddism — rejection of tech) vs. Technikdeterminismus (technological determinism)."},"examples":[{"german":"Technologische Innovation produziert nicht nur intendierte Wirkungen, sondern systematisch auch Nebenfolgen: Der Automobilisierung folgte eine massenhafte Umgestaltung von Städten für das Auto, mit Langzeitfolgen für Luftqualität, Siedlungsstrukturen und sozialen Zusammenhalt, die bei der Erfindung des Verbrennungsmotors niemand vorausgesehen hatte.","english":"Technological innovation produces not only intended effects, but systematically also side effects: mass motorisation was followed by a mass reshaping of cities for the car, with long-term consequences for air quality, settlement structures, and social cohesion that no one had foreseen at the time of the invention of the combustion engine."},{"german":"Das Vorsorgeprinzip der EU reflektiert eine kulturell verankerte Technikskepsis: Wo mögliche Schäden groß und irreversibel sein könnten, ist die Beweislast umgekehrt — nicht die Kritiker müssen beweisen, dass Technologie schädlich ist, sondern die Entwickler müssen die Unbedenklichkeit nachweisen.","english":"The EU''s precautionary principle reflects a culturally anchored technology scepticism: where possible harms could be large and irreversible, the burden of proof is reversed — not the critics must prove that technology is harmful, but the developers must demonstrate safety."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the precautionary principle, technology assessment, and unintended consequences at B2."}}',
'{"items":[{"word":"intendiert","translation":"intended","pronunciation":"in-ten-DEERT","example":"Intendierte Wirkungen."},{"word":"die Nebenfolge","translation":"side effect","pronunciation":"dee NAY-ben-fol-geh","example":"Systematische Nebenfolgen."},{"word":"die Beweislast","translation":"burden of proof","pronunciation":"dee beh-VYS-last","example":"Beweislast umkehren."},{"word":"umgekehrt","translation":"reversed","pronunciation":"oom-geh-KAYRT","example":"Beweislast ist umgekehrt."},{"word":"die Unbedenklichkeit","translation":"safety/harmlessness","pronunciation":"dee oon-beh-DENK-likh-kyt","example":"Unbedenklichkeit nachweisen."},{"word":"verankert","translation":"anchored/embedded","pronunciation":"fer-AN-kert","example":"Kulturell verankert."}]}',
'{"title":"Die Beweislast ist umgekehrt — the burden of proof is reversed (epistemic inversion)","pattern":"die Beweislast ist umgekehrt = the burden of proof is reversed (Beweislast = burden of proof — Beweis + Last; umgekehrt = reversed — past participle of umkehren = to reverse)","explanation":"Die Beweislast umkehren = to reverse the burden of proof (an important legal/regulatory concept). Normally: critics must prove harm (you are innocent until proven guilty). Reversed burden: developers must prove safety (precautionary principle). Die Beweislast liegt bei X = the burden of proof rests with X. Compare: in dubio pro reo (in case of doubt, in favour of the accused — standard criminal law) vs. Vorsorgeprinzip (precautionary principle — reversed burden for potential large harms). Beweislast key vocabulary: Nachweis (proof/evidence — nachweisen = to demonstrate), Belastung (burden — legal/rhetorical burden).","examples":[{"sentence":"Im Verwaltungsrecht liegt die Beweislast oft beim Bürger.","translation":"In administrative law, the burden of proof often lies with the citizen."},{"sentence":"Das neue Gesetz kehrt die Beweislast um — Unternehmen müssen beweisen, dass sie keine Schäden verursachen.","translation":"The new law reverses the burden of proof — companies must prove they cause no harm."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Intendiert'' means?","options":["intended","planned","deliberate","purposeful"],"correctAnswer":"intended"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The EU''s precautionary principle reflects a culturally anchored technology scepticism: where possible harms could be large and irreversible, the burden of proof is reversed — not the critics must prove that technology is harmful, but the developers must demonstrate safety.","options":["Das Vorsorgeprinzip der EU reflektiert eine kulturell verankerte Technikskepsis: Wo mögliche Schäden groß und irreversibel sein könnten, ist die Beweislast umgekehrt — nicht die Kritiker müssen beweisen, dass Technologie schädlich ist, sondern die Entwickler müssen die Unbedenklichkeit nachweisen.","Das EU-Vorsorgeprinzip verlangt, dass Technologie erst auf Schädlichkeit geprüft wird.","Das Vorsorgeprinzip stellt Sicherheit vor Innovation.","In der EU müssen Unternehmen die Sicherheit ihrer Technologien nachweisen."],"correctAnswer":"Das Vorsorgeprinzip der EU reflektiert eine kulturell verankerte Technikskepsis: Wo mögliche Schäden groß und irreversibel sein könnten, ist die Beweislast umgekehrt — nicht die Kritiker müssen beweisen, dass Technologie schädlich ist, sondern die Entwickler müssen die Unbedenklichkeit nachweisen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das neue Gesetz kehrt die Beweislast um — Unternehmen müssen beweisen, dass sie keine Schäden ___.","options":["verursachen","anrichten","erzeugen","produzieren"],"correctAnswer":"verursachen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In administrative law the burden of proof often lies with the citizen","wordBankItems":["Im","Verwaltungsrecht","liegt","die","Beweislast","oft","beim","Bürger","."],"correctAnswer":"Im Verwaltungsrecht liegt die Beweislast oft beim Bürger ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Verankert'' means?","options":["anchored/embedded","rooted","fixed","established"],"correctAnswer":"anchored/embedded"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

